#![cfg(feature = "audio")]
use seyk_core::{ResourceId, audio};

/// Historical capture helper: uses only APIs available at 7cab7ee.
/// In a clean 7cab7ee checkout, copy this file into crates/seyk-core/tests/,
/// then run (with fixtures generated by the PR's scripts/audio/timing.py):
///
/// SEYK_AUDIO_TIMING=/absolute/fixture/dir \
/// SEYK_AUDIO_CAPTURE_OUTPUT=crates/seyk-core/tests/fixtures/audio-input-hashes.json \
/// cargo test -p seyk-core --features audio --test audio_input_capture -- --include-ignored
///
/// Record `git rev-parse HEAD` and `git diff --exit-code` before copying this
/// helper. Compare the resulting JSON's window hashes/locators; container source
/// hashes can differ when fixture creation timestamps change. For a byte-for-byte
/// JSON diff, both captures must use the same physical fixture files.
#[test]
#[ignore = "requires scripts/audio/timing.py fixtures from the recorded baseline"]
fn capture_input_hashes() {
    let root = std::path::PathBuf::from(std::env::var("SEYK_AUDIO_TIMING").unwrap());
    let mut rows = std::collections::BTreeMap::new();
    for entry in std::fs::read_dir(&root).unwrap() {
        let path = entry.unwrap().path();
        let name = path.file_name().unwrap().to_string_lossy().to_string();
        if !matches!(
            path.extension().and_then(|s| s.to_str()),
            Some("wav" | "flac" | "mp3" | "m4a")
        ) || matches!(name.as_str(), "multi.m4a" | "he-aac.m4a")
        {
            continue;
        }
        let bytes = std::fs::read(&path).unwrap();
        let source_hash = blake3::hash(&bytes).to_hex().to_string();
        let id = ResourceId::from_path(&path).unwrap();
        let mut windows = Vec::new();
        audio::windows(bytes, &id, |locator, samples| {
            let mut hash = blake3::Hasher::new();
            hash.update(b"audio-input-v1");
            hash.update(audio::PREPARATION.as_bytes());
            let identity = b"fixture-audio-identity";
            hash.update(&(identity.len() as u64).to_le_bytes());
            hash.update(identity);
            hash.update(&(samples.len() as u64).to_le_bytes());
            for sample in &samples { hash.update(&sample.to_le_bytes()); }
            windows.push(serde_json::json!({"locator":locator,"input_hash":hash.finalize().to_hex().to_string()}));
            Ok(())
        }).unwrap();
        rows.insert(
            name,
            serde_json::json!({"source_hash":source_hash,"windows":windows}),
        );
    }
    let output = std::env::var("SEYK_AUDIO_CAPTURE_OUTPUT")
        .expect("set SEYK_AUDIO_CAPTURE_OUTPUT to the destination JSON");
    assert_eq!(
        rows.len(),
        18,
        "expected the complete timing and edge fixture set"
    );
    std::fs::write(output, serde_json::to_string_pretty(&rows).unwrap() + "\n").unwrap();
}
